INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Netzwerkgerät ohne Routing-Tabelle funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Routing-Tabelle steuert Datenfluss"}, {"text": "Ja", "correct": false, "because": "Ohne Tabelle keine Weiterleitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schicht des OSI-Modells nutzt ein Gerät zur Datenweiterleitung?', 3, '[{"text": "Schicht 3", "correct": true, "because": "Netzwerkschicht für IP-Adressen"}, {"text": "Schicht 2", "correct": false, "because": "Für Switches"}, {"text": "Schicht 7", "correct": false, "because": "Anwendungsschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle verwende ich für dynamisches Routing?', 5, '[{"text": "OSPF", "correct": true, "because": "Link-State-Protokoll"}, {"text": "BGP", "correct": true, "because": "Für externe Netze"}, {"text": "FTP", "correct": false, "because": "Für Dateitransfer"}, {"text": "HTTP", "correct": false, "because": "Für Web"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) NAT verbirgt private IP-Adressen. b) Es erhöht die Bandbreite.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, NAT beeinflusst Bandbreite nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Konfiguration eines Netzwerkgeräts?', 4, '[{"text": "IP-Adresse", "correct": false, "because": "Notwendig für Kommunikation"}, {"text": "Firewall-Regeln", "correct": false, "because": "Sichern Netzwerk"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Gerät ohne Modem das Internet erreicht?', 2, '[{"text": "Nein", "correct": true, "because": "Modem verbindet mit ISP"}, {"text": "Ja", "correct": false, "because": "Ohne Modem keine Internetverbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion verbessert die Sicherheit eines Netzwerkgeräts?', 4, '[{"text": "Firewall", "correct": true, "because": "Blockiert unerlaubten Zugriff"}, {"text": "Caching", "correct": false, "because": "Für Leistung"}, {"text": "DNS-Lookup", "correct": false, "because": "Für Namensauflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Netzwerkgerät immer WLAN bietet. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Nicht alle Geräte haben WLAN"}, {"text": "Ja", "correct": false, "because": "Viele sind kabelgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Switch dasselbe wie ein Netzwerkgerät?', 2, '[{"text": "Nein", "correct": true, "because": "Switch auf Schicht 2, Router auf Schicht 3"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt ein Netzwerkgerät?', 5, '[{"text": "Datenpaketweiterleitung", "correct": true, "because": "Verbindet Netzwerke"}, {"text": "NAT", "correct": true, "because": "Adressumsetzung"}, {"text": "Dateispeicherung", "correct": false, "because": "Für Server"}, {"text": "Grafikverarbeitung", "correct": false, "because": "Für GPUs"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einrichtung eines Netzwerkgeräts?', 4, '[{"text": "Sicherheitskonfiguration", "correct": true, "because": "Schützt vor Angriffen"}, {"text": "Schnelle Installation", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Design", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Gerät nutzt Routing-Protokolle. b) Es speichert alle Datenpakete.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Pakete werden weitergeleitet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Netzwerkverbindung?', 3, '[{"text": "IP-Adresse", "correct": false, "because": "Notwendig für Kommunikation"}, {"text": "Routing-Tabelle", "correct": false, "because": "Steuert Weiterleitung"}, {"text": "Touchscreen", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Verbindung eines Geräts sichere?', 4, '[{"text": "WPA3-Verschlüsselung aktivieren", "correct": true, "because": "Schützt WLAN"}, {"text": "Alle Ports öffnen", "correct": false, "because": "Erhöht Risiken"}, {"text": "Standardpasswort nutzen", "correct": false, "because": "Unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Gerät ohne Konfiguration funktioniert. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Konfiguration für Funktion nötig"}, {"text": "Ja", "correct": false, "because": "Ohne Einstellung ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie verbirgt private IP-Adressen?', 4, '[{"text": "NAT", "correct": true, "because": "Setzt private zu öffentlichen Adressen um"}, {"text": "VLAN", "correct": false, "because": "Segmentiert Netzwerke"}, {"text": "QoS", "correct": false, "because": "Priorisiert Datenverkehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Gerät mehrere Netzwerke verbinden?', 2, '[{"text": "Ja", "correct": true, "because": "Verbindet LAN und WAN"}, {"text": "Nein", "correct": false, "because": "Kernfunktion ist Verbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein modernes Netzwerkgerät?', 5, '[{"text": "Schnelle Datenweiterleitung", "correct": true, "because": "Verbessert Leistung"}, {"text": "VPN-Unterstützung", "correct": true, "because": "Sichert Verbindungen"}, {"text": "Bildverarbeitung", "correct": false, "because": "Nicht relevant"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verwaltung eines Geräts unwichtig?', 3, '[{"text": "Firmware-Updates", "correct": false, "because": "Sichern Stabilität"}, {"text": "Passwortänderung", "correct": false, "because": "Schützt Zugriff"}, {"text": "Standortdekoration", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich die Leistung eines Geräts verbessern will?', 4, '[{"text": "Firmware aktualisieren", "correct": true, "because": "Behebt Fehler, steigert Leistung"}, {"text": "Gerät neu lackieren", "correct": false, "because": "Kosmetisch"}, {"text": "Ports schließen", "correct": false, "because": "Einschränkt Funktion"}]');
